insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NL:carpenter','2026-08-11',null,19.00,39520,15,0,0,0,15,6,0,3,5,44,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7115 Carpenters and joiners; Dutch Timmerman scope.','shortage_note','UWV identifies construction and carpenter-related technical work as structurally promising; 15/20.','visa_basis','The Netherlands has no carpenter-specific migration fast track. Paid employment generally depends on the applicable IND work route, employer and permit conditions; 3/10.','salary_method','KiesMBO Timmerman BBL starting pay EUR 19/hour annualised at 2,080 hours; this is a transparent early-career proxy, not a national occupation median; 6/10.','entry_basis','Direct MBO level 2 Timmerman route, normally 1-2 years, with BBL work-study available; 15/15.','entry_burden_basis','No universal statutory carpenter register; 5/5.'),'2026-08-11'),
('NL:electrician','2026-08-11',null,18.00,37440,20,0,0,0,15,6,0,3,5,49,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7411 Building and related electricians; Dutch building-installation electrician scope.','shortage_note','UWV describes electrical and installation technicians as highly sought-after and the technical labour market remains tight to very tight; 20/20.','visa_basis','No electrician-specific residence or work-permit fast track is used. IND Highly Skilled Migrant/GVVA eligibility remains employer-, salary- and route-dependent; 3/10.','salary_method','KiesMBO Monteur elektrotechnische installaties BBL starting pay EUR 18/hour annualised at 2,080 hours; 6/10.','entry_basis','Direct MBO electrical-installation routes are available from level 2, with BBL pathways and strong current job prospects; 15/15.','entry_burden_basis','No single universal statutory electrician register is applied to the canonical occupation; 5/5.'),'2026-08-11'),
('NL:plumber','2026-08-11',null,17.00,35360,20,0,0,0,15,6,0,3,5,49,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7126 Plumbers and pipe fitters; Dutch loodgieter/installatiemonteur scope.','shortage_note','UWV explicitly cites plumbers among occupations with acute shortages in the first quarter of 2026; 20/20.','visa_basis','There is no plumber-specific Dutch migration fast track; standard paid-employment rules apply to non-EU workers; 3/10.','salary_method','KiesMBO Monteur werktuigkundige installaties starting pay EUR 17/hour annualised at 2,080 hours; 6/10.','entry_basis','Direct MBO level 2 installation route lasting about 1-2 years; 15/15.','entry_burden_basis','No universal plumber register. Gas-combustion-appliance work is restricted to CO-vrij certified companies, treated as task/company scope rather than universal personal registration; 5/5.'),'2026-08-11'),
('NL:wall-floor-tiler','2026-08-11',null,19.00,39520,15,0,0,0,15,6,0,3,5,44,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7122 Floor layers and tile setters; Dutch Tegelzetter scope.','shortage_note','UWV identifies floor-related finishing work and the wider construction segment as structurally promising, while KiesMBO reports strong tiling job prospects; 15/20.','visa_basis','No occupation-specific Dutch migration fast track; 3/10.','salary_method','KiesMBO Tegelzetter starting pay EUR 19/hour annualised at 2,080 hours; 6/10.','entry_basis','Direct MBO level 2 Tegelzetter route, normally 1-2 years, available through BOL/BBL; 15/15.','entry_burden_basis','No universal statutory tiler register; 5/5.'),'2026-08-11'),
('NL:welder','2026-08-11',null,15.00,31200,15,0,0,0,15,4,0,3,5,42,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7212 Welders and flame cutters; Dutch lasser scope.','shortage_note','UWV identifies welders among promising industrial occupations and persistent technical shortages; 15/20.','visa_basis','No welder-specific Dutch migration fast track; 3/10.','salary_method','KiesMBO Medewerker productietechniek, which explicitly covers welding, has EUR 15/hour starting pay; annualised at 2,080 hours and transparently used as a welding-entry proxy; 4/10.','entry_basis','MBO level 2 production-technology route covers welding and metal fabrication in 1-2 years; 15/15.','entry_burden_basis','No universal statutory welder register; project-specific welding qualifications may be required; 5/5.'),'2026-08-11'),
('NL:bricklayer','2026-08-11',null,19.00,39520,20,0,0,0,15,6,0,3,5,49,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7112 Bricklayers and related workers; Dutch Metselaar scope.','shortage_note','UWV explicitly added bricklayers and jointers to the national promising-occupations list in 2026; 20/20.','visa_basis','No bricklayer-specific migration fast track; 3/10.','salary_method','KiesMBO Metselaar starting pay EUR 19/hour annualised at 2,080 hours; 6/10.','entry_basis','Direct MBO level 2 Metselaar route, normally 1-2 years, with progression to allround level 3; 15/15.','entry_burden_basis','No universal statutory bricklayer register; 5/5.'),'2026-08-11'),
('NL:hvac-technician','2026-08-11',null,18.00,37440,20,0,0,0,15,6,0,3,2,46,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 7127 Air conditioning and refrigeration mechanics; Dutch koude-, klimaat- and heat-pump technician scope.','shortage_note','UWV identifies heat-pump, cooling and installation technicians as very promising amid persistent installation-sector shortages; 20/20.','visa_basis','No HVAC-specific Dutch migration fast track; standard employment routes remain employer- and permit-dependent; 3/10.','salary_method','KiesMBO Monteur koude- en klimaatsystemen starting pay EUR 18/hour annualised at 2,080 hours; 6/10.','entry_basis','Direct MBO level 2 cooling/climate route is 1-2 years and current job prospects are very strong; 15/15.','entry_burden_basis','Relevant refrigerant work requires personal certification under the revised F-gas/BRL 200 system from 29 March 2026; 2/5.'),'2026-08-11'),
('NL:construction-manager','2026-08-11',null,19.08,38688,20,0,0,0,8,6,0,3,5,42,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 1323 Construction managers; Dutch construction project-lead/uitvoerder management scope.','shortage_note','UWV reports strong demand for higher-level construction professionals and expects tightening for production leaders in construction; 20/20.','visa_basis','Construction management has no occupation-specific migration fast track. Highly Skilled Migrant access requires a recognised sponsor and the applicable salary criterion, so generic occupation credit remains 3/10.','salary_method','Studiekeuze123 Built Environment associate-degree graduate starting salary EUR 3,224/month, annualised to EUR 38,688 and used as a transparent early-career built-environment proxy rather than an occupation-wide manager median; 6/10.','entry_basis','MBO level 4 construction coordination plus HBO Built Environment and project experience provide common routes; management responsibility generally requires more progression than the level-2 trades; 8/15.','entry_burden_basis','No universal statutory construction-manager register; 5/5.'),'2026-08-11')
